import datetime,fcntl,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def main():
 plan=H/'gpu-recency-frozen-plan-nov3.json';m=json.loads(plan.read_text());state=json.loads((H/'live-nov3-gpu-recency-custody.json').read_text());a=json.loads((H/'live-nov3-gpu-recency-independent-analysis.json').read_text());rows=list(a['rows'].values())
 assert sha(plan)==state['manifest_sha256'];bad=[p for p,v in m['file_pins'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=v];assert not bad
 assert state['status']=='complete' and len(state['runs'])==9 and not state['owned_descendants_remaining']
 if psutil.pid_exists(state['supervisor_pid']):assert psutil.Process(state['supervisor_pid']).create_time()!=state['supervisor_create_time']
 assert all(r['owned_descendants_remaining']==[] for r in rows)
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 before=shutil.disk_usage(H).free;files=[]
 for item in m['execution_order']:
  files.extend(p for p in (H/'runs'/item['name']).rglob('*') if p.is_file());files.append(H/(item['name']+'-driver-console.log.gz'))
 assert all(p.exists() for p in files);assert not any(p.suffix in ['.log','.jsonl'] for p in files)
 assessment={'schema':'astra-GPU-recency-discovery-assessment-v1','plan_sha256':sha(plan),'all9eligible':all(r['eligible'] for r in rows),'production_endorsement':False,'natural_eos':sum(r['natural_eos'] for r in rows),'all_policy_receipts_valid':all(r['gpu_recency_receipt']['qualified'] for r in rows),'HTTP':{'attempts':sum(r['HTTP_receipt']['expected_total_HTTP_requests'] for r in rows),'generations':sum(r['HTTP_receipt']['generation_rows'] for r in rows),'hints':sum(r['HTTP_receipt']['hint_rows'] for r in rows),'intentional_hint_cancellations':sum(len(r['HTTP_receipt']['intentional_hint_cancellations']) for r in rows),'unexpected_exceptions':sum(len(r['HTTP_receipt']['unexpected_transport_exceptions']) for r in rows),'connection_reuse':sum(r['HTTP_receipt']['counts']['connection_reuse'] for r in rows)},'all_zero_preemptions':all(r['first_prefill_attribution']['preemptions']==0 for r in rows),'first_admission_reconciles_all':all(r['first_prefill_attribution']['reconciles'] is True for r in rows),'store_accept_complete_balanced_all':all(r['store_balance']['balanced'] is True for r in rows),'explicit_store_failure_counter':'Unavailable, not assumed zero.','comparisons':a['comparisons'],'resource_and_mechanism_rows':{r['name']:{k:r[k] for k in ['load_s','tokens','tokens_s','tokens_s_per_gib','ttft_ms','e2e_ms','resources','host_resources','thermal_clock_power','first_prefill_attribution','restoration_accounting','transfers','scheduler_counts','service_format','configuration_activation']} for r in rows},'GPU_operation_receipts':{r['name']:{k:r['gpu_recency_receipt'][k] for k in ['expected_GPU_policy','actual_refresh_operations','eligible_free_block_operations','ACKs_with_positive_refresh','replayed_ACKs_excluded','per_hint','per_wait_first','per_wait_last','hint_response_reasons']} for r in rows},'quality':json.loads((H/'live-nov3-gpu-recency-quality-review.json').read_text()),'independent_interpretation':json.loads((H/'live-nov3-gpu-recency-interpretation.json').read_text()),'limitations':['One workflow per arm per spent partition, balanced three-arm Latin order: discovery only, no confidence intervals or production claim.','Operational queue walks and lookups are real candidate costs; controls have no dummy scan. No standalone GPU byte qualification of this changed eviction policy yet.','Coverage snapshots precede mutation; repeated key-operation counts are not unique bytes, future survival or demand hits. Comparisons with earlier observation-only runs are descriptive and affected by changed timing/batches.','First-admission token attribution is not cumulative physical executed prefill. Native transfer totals reported separately.','Natural output lengths vary; token rate and workflow rate must both be considered.','Sampled RSS may double count shared pages; system RAM/swap and thermal observations are not uniquely attributed to policy. Actual locked host-memory bytes unavailable.','Native control uses common correctness-normalized runtime overlay, not an unpatched wheel.','Known baseline reasoning/format defects require human review; quality equivalence, task success and productivity unqualified.','4096-identity registry saturation and continuous endurance still unqualified.']}
 write(H/'live-nov3-gpu-recency-independent-assessment.json',assessment)
 inventory={'schema':'astra-GPU-recency-handback-v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','pins_checked':len(m['file_pins']),'pin_mismatches':bad,'supervisor_exited':True,'all_runner_descendants_exited':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'free_bytes_before_cleanup':before,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'removed_files':[],'retained_bytes':sum(p.stat().st_size for p in files),'retained_files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size} for p in files],'reason':'Useful raw evidence, per-run archives and compressed logs preserved. No disposable downloads/worktrees/checkpoints/uncompressed logs/owned processes remain. All previous shared results/caches untouched.'};write(H/'live-nov3-gpu-recency-handback-inventory.json',inventory)
 print(json.dumps({'HTTP':assessment['HTTP'],'natural_eos':assessment['natural_eos'],'retained_bytes':inventory['retained_bytes'],'cleanup_complete':True},indent=2))
if __name__=='__main__':main()
